-- PostgreSQL starter schema. Apply through a reviewed migration process in production.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), idp_subject TEXT NOT NULL, email TEXT NOT NULL, display_name TEXT, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id,idp_subject), UNIQUE(tenant_id,email));
CREATE TABLE domains (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT);
CREATE TABLE controls (id TEXT PRIMARY KEY, domain_id TEXT NOT NULL REFERENCES domains(id), control_number INT NOT NULL, category TEXT NOT NULL, title TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('High','Medium','Low')), owner_role TEXT, framework_refs JSONB NOT NULL DEFAULT '[]', evidence_guidance TEXT, catalogue_version TEXT NOT NULL DEFAULT '2.0', UNIQUE(domain_id,control_number));
CREATE TABLE assessments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, period_start DATE, period_end DATE, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE control_assessments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), assessment_id UUID NOT NULL REFERENCES assessments(id), control_id TEXT NOT NULL REFERENCES controls(id), status TEXT NOT NULL CHECK(status IN ('Not Started','In Progress','Complete','N/A')), applicability_reason TEXT, owner_user_id UUID REFERENCES users(id), assessor_user_id UUID REFERENCES users(id), assessed_at TIMESTAMPTZ, target_date DATE, notes TEXT, remediation_plan TEXT, version INT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(assessment_id,control_id));
CREATE TABLE evidence_objects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), control_assessment_id UUID REFERENCES control_assessments(id), storage_key TEXT NOT NULL, filename TEXT NOT NULL, media_type TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK(size_bytes >= 0), sha256 CHAR(64) NOT NULL, classification TEXT NOT NULL CHECK(classification IN ('Public','Internal','Confidential','Restricted')), uploaded_by UUID REFERENCES users(id), uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(), retention_until DATE, legal_hold BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE risks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), risk_key TEXT NOT NULL, title TEXT NOT NULL, description TEXT, likelihood SMALLINT CHECK(likelihood BETWEEN 1 AND 5), impact SMALLINT CHECK(impact BETWEEN 1 AND 5), inherent_score SMALLINT, residual_score SMALLINT, owner_user_id UUID REFERENCES users(id), treatment TEXT, status TEXT NOT NULL DEFAULT 'Open', review_date DATE, UNIQUE(tenant_id,risk_key));
CREATE TABLE findings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), finding_key TEXT NOT NULL, title TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('Critical','High','Medium','Low','Observation')), description TEXT, root_cause TEXT, recommendation TEXT, owner_user_id UUID REFERENCES users(id), due_date DATE, status TEXT NOT NULL DEFAULT 'Open', validated_by UUID REFERENCES users(id), closed_at TIMESTAMPTZ, UNIQUE(tenant_id,finding_key));
CREATE TABLE audit_events (id BIGSERIAL PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenants(id), actor_user_id UUID REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), source_ip INET, request_id TEXT, before_hash CHAR(64), after_hash CHAR(64), metadata JSONB NOT NULL DEFAULT '{}');
CREATE INDEX idx_assessments_tenant ON assessments(tenant_id);
CREATE INDEX idx_control_assessments_tenant_status ON control_assessments(tenant_id,status);
CREATE INDEX idx_evidence_assessment ON evidence_objects(control_assessment_id);
CREATE INDEX idx_risks_tenant_status ON risks(tenant_id,status);
CREATE INDEX idx_findings_tenant_status_due ON findings(tenant_id,status,due_date);
CREATE INDEX idx_audit_events_tenant_time ON audit_events(tenant_id,occurred_at DESC);
-- Production: enforce tenant isolation with PostgreSQL row-level security policies;
-- use separate migration/runtime roles and deny UPDATE/DELETE on audit_events to app role.
